<script setup>
import { computed, onMounted, ref } from "vue";import { api, normalizeList } from "../../services/api";
const items=ref([]),departments=ref([]),loading=ref(true),saving=ref(false),error=ref(""),filter=ref(""),showForm=ref(false),editing=ref(null);
const form=ref({name:"",category:"Office Equipment",itemCode:"",serialNumber:"",quantity:1,availableQuantity:1,unit:"unit",status:"Available",ownerDepartment:"",custodian:"",location:"",purchaseDate:"",notes:""});const employees=ref([]);
const filtered=computed(()=>filter.value?items.value.filter(i=>String(i.ownerDepartment?._id||i.ownerDepartment)===filter.value):items.value);
function reset(){editing.value=null;form.value={name:"",category:"Office Equipment",itemCode:"",serialNumber:"",quantity:1,availableQuantity:1,unit:"unit",status:"Available",ownerDepartment:filter.value||"",custodian:"",location:"",purchaseDate:"",notes:""};showForm.value=true;}
function edit(i){editing.value=i._id;form.value={...form.value,...i,ownerDepartment:i.ownerDepartment?._id||"",custodian:i.custodian?._id||"",purchaseDate:i.purchaseDate?String(i.purchaseDate).slice(0,10):""};showForm.value=true;}
async function load(){loading.value=true;try{const [i,d,e]=await Promise.all([api.listInventory(),api.listDepartments(),api.listEmployees()]);items.value=normalizeList(i);departments.value=normalizeList(d);employees.value=normalizeList(e);}catch(e){error.value=e.message||"Unable to load inventory.";}finally{loading.value=false;}}
async function save(){saving.value=true;error.value="";try{const payload={...form.value,quantity:Number(form.value.quantity),availableQuantity:Number(form.value.availableQuantity),ownerDepartment:form.value.ownerDepartment||null,custodian:form.value.custodian||null};if(editing.value)await api.updateInventory(editing.value,payload);else await api.createInventory(payload);showForm.value=false;await load();}catch(e){error.value=e.message||"Unable to save inventory item.";}finally{saving.value=false;}}
async function remove(i){if(!confirm(`Retire ${i.name}?`))return;try{await api.deleteInventory(i._id);await load();}catch(e){error.value=e.message||"Unable to retire item.";}}
onMounted(load);
</script>
<template><div class="page"><div class="page-header"><div><span class="page-kicker">INVENTORY</span><h1>Company inventory</h1><p>Keep separate ownership by department—Administration, IT or any other team—and record who physically keeps each item.</p></div><button class="btn btn-primary" @click="reset">+ Add inventory</button></div><div v-if="error" class="alert alert-error">{{error}}</div><section class="inventory-toolbar card"><label>Owner department<select v-model="filter" class="input"><option value="">All departments</option><option v-for="d in departments" :key="d._id" :value="d._id">{{d.name}}</option></select></label><span>{{filtered.length}} items</span></section><section v-if="showForm" class="card form-card"><div class="builder-title"><div><span class="page-kicker">INVENTORY RECORD</span><h2>{{editing?'Edit item':'Add item'}}</h2></div><button class="btn btn-secondary" @click="showForm=false">Close</button></div><div class="form-row"><label>Item name<input v-model="form.name" class="input"/></label><label>Category<input v-model="form.category" class="input"/></label></div><div class="form-row"><label>Item code<input v-model="form.itemCode" class="input"/></label><label>Serial number<input v-model="form.serialNumber" class="input"/></label></div><div class="form-row"><label>Owner department<select v-model="form.ownerDepartment" class="input"><option value="">Company / unassigned</option><option v-for="d in departments" :key="d._id" :value="d._id">{{d.name}}</option></select></label><label>Custodian<select v-model="form.custodian" class="input"><option value="">Not assigned</option><option v-for="e in employees" :key="e._id" :value="e._id">{{e.firstName}} {{e.lastName}}</option></select></label></div><div class="form-row"><label>Quantity<input v-model.number="form.quantity" class="input" type="number" min="0"/></label><label>Available<input v-model.number="form.availableQuantity" class="input" type="number" min="0"/></label></div><div class="form-row"><label>Location<input v-model="form.location" class="input" placeholder="IT store / Admin store / Floor 2"/></label><label>Status<select v-model="form.status" class="input"><option>Available</option><option>Assigned</option><option>Low Stock</option><option>Damaged</option><option>Retired</option></select></label></div><label>Notes<textarea v-model="form.notes" class="textarea" rows="3"></textarea></label><div class="form-actions"><button class="btn btn-primary" :disabled="saving" @click="save">{{saving?'Saving…':'Save item'}}</button></div></section><section class="card"><div v-if="loading" class="empty-state">Loading inventory…</div><div v-else-if="!filtered.length" class="empty-state">No inventory records yet.</div><div v-else class="inventory-list"><article v-for="item in filtered" :key="item._id" class="inventory-row"><div class="inventory-icon">▦</div><div><strong>{{item.name}}</strong><span>{{item.category}} · {{item.itemCode||"No code"}} · {{item.serialNumber||"No serial"}}</span><small>{{item.ownerDepartment?.name||"Company"}} · Custodian: {{item.custodian?`${item.custodian.firstName} ${item.custodian.lastName}`:"Not assigned"}}</small></div><div class="inventory-qty"><strong>{{item.availableQuantity}} / {{item.quantity}}</strong><span>{{item.status}}</span></div><div class="employee-actions"><button class="btn btn-secondary" @click="edit(item)">Edit</button><button class="btn btn-secondary" @click="remove(item)">Retire</button></div></article></div></section></div></template>
